package com.unipampa.compiladorarquitetura16bits;

import java.util.*;
import java.util.regex.Pattern;

public class Compiler {

    // Mapa para armazenar labels e seus endereços
    private Map<String, Integer> labels = new HashMap<>();

    // Lista para armazenar o código compilado
    private List<String> compiledCode = new ArrayList<>();

    // Contador de endereços
    private int currentAddress = 0;

    public String compile(String sourceCode) throws Exception {
        if (sourceCode == null || sourceCode.trim().isEmpty()) {
            throw new Exception("Código fonte vazio");
        }

        // Reset do estado
        labels.clear();
        compiledCode.clear();
        currentAddress = 0;

        String[] lines = sourceCode.split("\n");

        // Primeira passada: identificar labels
        firstPass(lines);

        // Segunda passada: gerar código
        secondPass(lines);

        return generateOutput();
    }

    private void firstPass(String[] lines) throws Exception {
        currentAddress = 0;

        for (String line : lines) {
            line = line.trim();

            // Ignorar linhas vazias e comentários
            if (line.isEmpty() || line.startsWith(";")) {
                continue;
            }

            // Verificar se é um label
            if (line.endsWith(":")) {
                String label = line.substring(0, line.length() - 1).trim();
                if (labels.containsKey(label)) {
                    throw new Exception("Label duplicado: " + label);
                }
                labels.put(label, currentAddress);
            } else {
                // É uma instrução, incrementar endereço
                currentAddress++;
            }
        }
    }

    private void secondPass(String[] lines) throws Exception {
        currentAddress = 0;

        for (String line : lines) {
            line = line.trim();

            // Ignorar linhas vazias e comentários
            if (line.isEmpty() || line.startsWith(";")) {
                continue;
            }

            // Ignorar labels
            if (line.endsWith(":")) {
                continue;
            }

            // Compilar instrução
            String compiled = compileInstruction(line, currentAddress);
            compiledCode.add(String.format("%04d: %s", currentAddress, compiled));
            currentAddress++;
        }
    }

    private String compileInstruction(String instruction, int address) throws Exception {
        String[] parts = instruction.split("\\s+");
        String opcode = parts[0].toUpperCase();

        switch (opcode) {
            case "LDA":
                return compileLDA(parts);
            case "SUM":
                return compileSUM(parts);
            case "SUB":
                return compileSUB(parts);
            case "MUL":
                return compileMUL(parts);
            case "JMP":
                return compileJMP(parts);
            case "BEQ":
                return compileBEQ(parts);
            case "BNE":
                return compileBNE(parts);
            default:
                throw new Exception("Instrução não reconhecida: " + opcode);
        }
    }

    // Compilação das instruções do Grupo 1 - Aritmética
    private String compileLDA(String[] parts) throws Exception {
        if (parts.length != 3) {
            throw new Exception("LDA: Sintaxe incorreta. Use: LDA Rdest, valor_imediato");
        }

        int destReg = parseRegister(parts[1]);
        int value = parseValue(parts[2]);

        // Formato: OPCODE(4) + REG_DEST(3) + VALOR(9)
        return String.format("0001%03d%09d", destReg, value & 0x1FF);
    }

    private String compileSUM(String[] parts) throws Exception {
        if (parts.length != 4) {
            throw new Exception("SUM: Sintaxe incorreta. Use: SUM Rdest, Rf1, Rf2");
        }

        int destReg = parseRegister(parts[1]);
        int reg1 = parseRegister(parts[2]);
        int reg2 = parseRegister(parts[3]);

        // Formato: OPCODE(4) + REG_DEST(3) + REG1(3) + REG2(3) + UNUSED(3)
        return String.format("0010%03d%03d%03d000", destReg, reg1, reg2);
    }

    private String compileSUB(String[] parts) throws Exception {
        if (parts.length != 4) {
            throw new Exception("SUB: Sintaxe incorreta. Use: SUB Rdest, Rf1, Rf2");
        }

        int destReg = parseRegister(parts[1]);
        int reg1 = parseRegister(parts[2]);
        int reg2 = parseRegister(parts[3]);

        return String.format("0011%03d%03d%03d000", destReg, reg1, reg2);
    }

    private String compileMUL(String[] parts) throws Exception {
        if (parts.length != 4) {
            throw new Exception("MUL: Sintaxe incorreta. Use: MUL Rdest, Rf1, Rf2");
        }

        int destReg = parseRegister(parts[1]);
        int reg1 = parseRegister(parts[2]);
        int reg2 = parseRegister(parts[3]);

        return String.format("0100%03d%03d%03d000", destReg, reg1, reg2);
    }

    // Compilação das instruções do Grupo 2 - Controle de Fluxo
    private String compileJMP(String[] parts) throws Exception {
        if (parts.length != 2) {
            throw new Exception("JMP: Sintaxe incorreta. Use: JMP endereço");
        }

        int address = parseAddress(parts[1]);

        // Formato: OPCODE(4) + ENDERECO(12)
        return String.format("1001%012d", address);
    }

    private String compileBEQ(String[] parts) throws Exception {
        if (parts.length != 4) {
            throw new Exception("BEQ: Sintaxe incorreta. Use: BEQ Rf1, Rf2, endereço");
        }

        int reg1 = parseRegister(parts[1]);
        int reg2 = parseRegister(parts[2]);
        int address = parseAddress(parts[3]);

        // Formato: OPCODE(4) + REG1(3) + REG2(3) + ENDERECO(6)
        return String.format("1010%03d%03d%06d", reg1, reg2, address);
    }

    private String compileBNE(String[] parts) throws Exception {
        if (parts.length != 4) {
            throw new Exception("BNE: Sintaxe incorreta. Use: BNE Rf1, Rf2, endereço");
        }

        int reg1 = parseRegister(parts[1]);
        int reg2 = parseRegister(parts[2]);
        int address = parseAddress(parts[3]);

        return String.format("1011%03d%03d%06d", reg1, reg2, address);
    }

    // Métodos auxiliares
    private int parseRegister(String reg) throws Exception {
        reg = reg.replace(",", "").trim();

        if (!reg.matches("[Rr][0-7]")) {
            throw new Exception("Registrador inválido: " + reg + ". Use R0-R7");
        }

        return Integer.parseInt(reg.substring(1));
    }

    private int parseValue(String value) throws Exception {
        value = value.replace(",", "").trim();

        try {
            int val = Integer.parseInt(value);
            if (val < 0 || val > 511) { // 9 bits = 0-511
                throw new Exception("Valor fora do range (0-511): " + val);
            }
            return val;
        } catch (NumberFormatException e) {
            throw new Exception("Valor inválido: " + value);
        }
    }

    private int parseAddress(String address) throws Exception {
        address = address.replace(",", "").trim();

        // Verificar se é um label
        if (labels.containsKey(address)) {
            return labels.get(address);
        }

        // Senão, tentar como número
        try {
            int addr = Integer.parseInt(address);
            if (addr < 0 || addr > 4095) { // 12 bits = 0-4095
                throw new Exception("Endereço fora do range (0-4095): " + addr);
            }
            return addr;
        } catch (NumberFormatException e) {
            throw new Exception("Endereço ou label inválido: " + address);
        }
    }

    private String generateOutput() {
        StringBuilder output = new StringBuilder();
        output.append("=== CÓDIGO COMPILADO ===\n");
        output.append("Formato: Endereço: Código Binário (16 bits)\n\n");

        for (String line : compiledCode) {
            output.append(line).append("\n");
        }

        output.append("\n=== LABELS ENCONTRADOS ===\n");
        for (Map.Entry<String, Integer> entry : labels.entrySet()) {
            output.append(String.format("%s: %04d\n", entry.getKey(), entry.getValue()));
        }

        return output.toString();
    }
}

* {
    -fx-cor-primaria: #eefbee;
    -fx-fonte-principal: "Segoe UI", Tahoma, Geneva, Verdana, sans-serif;
}

.tela-principal {
    -fx-font-family: -fonte-principal;
    -fx-background-color: -fx-cor-primaria;
}

.rodape {
    -fx-background-color: -fx-cor-primaria;
    -fx-text-fill: white;
    -fx-padding: 10px;
    -fx-alignment: center;
}

.rodape-error {
    -fx-background-color: #c0392b;
    -fx-text-fill: white;
    -fx-padding: 10px;
    -fx-alignment: center;
}

.label-rodape {
    -fx-font-size: 14px;
    -fx-text-fill: #000000;

}

